package com.example;

import java.util.List;

public class CsvWriter {
    public String write(List<String[]> rows) {
        String out = "";
        for (String[] row : rows) {
            for (String cell : row) {
                out = out + cell + ",";
            }
            out = out + "\n";
        }
        return out;
    }
}

